 static void Footing(GameObject root,string name,List<Vector2> shape,float top,float expand){if(shape.Count<3)throw new Exception("No footprint "+name);var center=shape.Aggregate(Vector2.zero,(a,b)=>a+b)/shape.Count;shape=shape.Select(p=>p+(p-center).normalized*expand).ToList();var verts=new List<Vector3>();var uv=new List<Vector2>();var tris=new List<int>();float distance=0;for(int i=0;i<shape.Count;i++){var a=shape[i];var b=shape[(i+1)%shape.Count];float len=Vector2.Distance(a,b);int steps=Mathf.CeilToInt(len/.65f);for(int k=0;k<steps;k++){var p=Vector2.Lerp(a,b,(float)k/steps);var q=Vector2.Lerp(a,b,(float)(k+1)/steps);float hp=GH(p.x,p.y),hq=GH(q.x,q.y);if(float.IsNaN(hp)||float.IsNaN(hq))throw new Exception("Footing outside Boss_Area "+name);float yp=Mathf.Min(top-.15f,hp-.38f),yq=Mathf.Min(top-.15f,hq-.38f);int j=verts.Count;verts.AddRange(new[]{new Vector3(p.x,yp,p.y),new Vector3(p.x,top,p.y),new Vector3(q.x,top,q.y),new Vector3(q.x,yq,q.y)});float u=distance+len*k/steps,w=distance+len*(k+1)/steps;uv.AddRange(new[]{new Vector2(u/3,yp/3),new Vector2(u/3,top/3),new Vector2(w/3,top/3),new Vector2(w/3,yq/3)});tris.AddRange(new[]{j,j+1,j+2,j,j+2,j+3});}distance+=len;}
 int ci=verts.Count;verts.Add(new Vector3(center.x,top,center.y));uv.Add(center/3);foreach(var p in shape){verts.Add(new Vector3(p.x,top,p.y));uv.Add(p/3);}for(int i=0;i<shape.Count;i++)tris.AddRange(new[]{ci,ci+1+(i+1)%shape.Count,ci+1+i});var mesh=new Mesh(){name=name};mesh.SetVertices(verts);mesh.SetUVs(0,uv);mesh.SetTriangles(tris,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();string asset=GF+name.Replace(" ","_")+".asset";AssetDatabase.CreateAsset(mesh,asset);var go=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer),typeof(MeshCollider));go.transform.SetParent(root.transform,false);go.transform.position=Vector3.zero;go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshRenderer>().sharedMaterial=FoundationMat();go.GetComponent<MeshCollider>().sharedMesh=mesh;go.isStatic=true;}
