 Physics.SyncTransforms();var log=new System.Text.StringBuilder();foreach(var item in report.items.Where(i=>i.name.StartsWith("Ledge growth in ruined bay")||(i.group.StartsWith("07")&&i.minGap>.04f))){var g=GameObject.Find(item.name);if(!g)continue;float support=GH(item.position.x,item.position.z);foreach(var hit in Physics.RaycastAll(new Vector3(item.position.x,item.min.y+.08f,item.position.z),Vector3.down,30)){if(hit.collider.transform.IsChildOf(g.transform)||hit.collider is TerrainCollider)continue;var rootTr=hit.collider.transform;bool foliage=false;while(rootTr&&rootTr!=arena.transform){if(rootTr.name.StartsWith("08 -")){foliage=true;break;}rootTr=rootTr.parent;}if(!foliage&&hit.point.y<=item.min.y+.08f)support=Mathf.Max(support,hit.point.y);}float delta=support-item.min.y-.02f;if(delta<-.08f){Undo.RecordObject(g.transform,"Seat floating detail");g.transform.position+=Vector3.up*delta;PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);log.AppendLine(item.name+" lowered "+(-delta).ToString("F3")+"m onto "+support);}}
