 static GameObject[] HouseParts(){return Enumerable.Range(1,5).Select(i=>GameObject.Find("West cloister bay "+i)).ToArray();}
 static void HouseFix(){
 if(GameObject.Find("West cloister continuous raised foundation"))throw new Exception("House already repaired");
 var parts=HouseParts();var pts=parts.SelectMany(g=>Points(g)).ToArray();float oldBase=pts.Min(p=>p.y);float high=-1000;for(float x=190.2f;x<=197.8f;x+=.1f)for(float z=148.9f;z<=189.1f;z+=.1f)high=Mathf.Max(high,GH(x,z));float top=high+.10f,delta=top-oldBase;
 Undo.SetCurrentGroupName("Unbury west cloister building");foreach(var g in parts){Undo.RecordObject(g.transform,"Raise joined house section");g.transform.position+=Vector3.up*delta;PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);}
 foreach(var name in new[]{"Ledge growth in ruined bay 1","Ledge growth in ruined bay 2"}){var g=GameObject.Find(name);Undo.RecordObject(g.transform,"Keep ledge growth on house");g.transform.position+=Vector3.up*delta;PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);}
 var root=GameObject.Find("11 - Terrain-fitted foundations");var low=pts.Where(p=>p.y<oldBase+.18f);Footing(root,"West cloister continuous raised foundation",Hull(low),top+.035f,.15f);
 foreach(var name in new[]{"West cloister bay 4 stone footing","West cloister bay 5 stone footing"}){var g=GameObject.Find(name);Undo.RecordObject(g,"Superseded by continuous foundation");g.SetActive(false);}
 var log=new System.Text.StringBuilder();log.AppendLine("Raised all five sections by "+delta+" metres; base="+top+"; maximum original terrain="+high);
 for(int i=0;i<5;i++){float z=153.115f+i*8;BuildHouseSteps(root,i+1,z,top,log);}
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());File.WriteAllText(HD+"repair.txt",log.ToString());HouseVerify();
 }
 static void BuildHouseSteps(GameObject parent,int number,float z,float top,System.Text.StringBuilder log){
 var vv=new List<Vector3>();var uv=new List<Vector2>();var tt=new List<int>();Action<Vector3,Vector3,Vector3,Vector3> quad=(a,b,c,d)=>{int j=vv.Count;vv.AddRange(new[]{a,b,c,d});var n=Vector3.Cross(b-a,c-a).normalized;foreach(var p in new[]{a,b,c,d})uv.Add(Mathf.Abs(n.y)>.5f?new Vector2(p.x,p.z)/3:Mathf.Abs(n.x)>.5f?new Vector2(p.z,p.y)/3:new Vector2(p.x,p.y)/3);tt.AddRange(new[]{j,j+1,j+2,j,j+2,j+3});};
 int count=0;float toeGap=0;for(int k=0;k<35;k++){float x=197.66f+k*.34f,x2=x+.342f,z1=z-.95f,z2=z+.95f,h=top-k*.17f;float ground=Mathf.Min(GH(x2,z1),GH(x2,z2));if(k==0&&ground>=h+.15f)break;
 float y1=Mathf.Min(h-.12f,GH(x,z1)-.25f),y2=Mathf.Min(h-.12f,GH(x,z2)-.25f),y3=Mathf.Min(h-.12f,GH(x2,z2)-.25f),y4=Mathf.Min(h-.12f,GH(x2,z1)-.25f);
 var a=new Vector3(x,h,z1);var b=new Vector3(x,h,z2);var c=new Vector3(x2,h,z2);var d=new Vector3(x2,h,z1);quad(a,b,c,d);quad(new Vector3(x,y1,z1),a,d,new Vector3(x2,y4,z1));quad(new Vector3(x2,y3,z2),c,b,new Vector3(x,y2,z2));quad(new Vector3(x2,y4,z1),d,c,new Vector3(x2,y3,z2));quad(new Vector3(x,y2,z2),b,a,new Vector3(x,y1,z1));count++;toeGap=h-ground;if(toeGap<=.18f)break;}
 if(count==0)return;var mesh=new Mesh{name="West cloister entrance steps "+number};mesh.SetVertices(vv);mesh.SetUVs(0,uv);mesh.SetTriangles(tt,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,GF+"West_cloister_entrance_steps_"+number+".asset");var go=new GameObject(mesh.name,typeof(MeshFilter),typeof(MeshRenderer),typeof(MeshCollider));go.transform.SetParent(parent.transform,false);go.transform.position=Vector3.zero;go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshRenderer>().sharedMaterial=FoundationMat();go.GetComponent<MeshCollider>().sharedMesh=mesh;go.isStatic=true;log.AppendLine("Entrance "+number+": "+count+" treads; last tread terrain gap="+toeGap);}
 static void HouseVerify(){Physics.SyncTransforms();var root=GameObject.Find("West cloister continuous raised foundation");var collider=root.GetComponent<MeshCollider>();var log=new System.Text.StringBuilder();int count=0,bad=0;foreach(var g in HouseParts()){var pts=Points(g);float min=pts.Min(p=>p.y);float gap=0;foreach(var p in pts.Where(p=>p.y<min+.18f)){RaycastHit hit;float support=GH(p.x,p.z);if(collider.Raycast(new Ray(new Vector3(p.x,100,p.z),Vector3.down),out hit,150))support=Mathf.Max(support,hit.point.y);gap=Mathf.Max(gap,min-support);count++;if(min-support>.1f)bad++;}log.AppendLine(g.name+" base="+min+" maximum support gap="+gap);}float high=-1000;for(float x=190.2f;x<=197.8f;x+=.1f)for(float z=148.9f;z<=189.1f;z+=.1f)high=Mathf.Max(high,GH(x,z));log.AppendLine("Maximum underlying terrain="+high+"; "+count+" base vertex checks; unsupported="+bad);File.WriteAllText(HD+"verification.txt",log.ToString());}
