 static void HouseSurvey(){var sb=new System.Text.StringBuilder();sb.AppendLine("Dirty before save: "+SceneManager.GetActiveScene().isDirty);EditorSceneManager.SaveScene(SceneManager.GetActiveScene());File.Copy(S,HD+"scene-before.unity",true);var view=SceneView.lastActiveSceneView;if(view){sb.AppendLine("Scene camera "+view.camera.transform.position+" rotation "+view.camera.transform.eulerAngles);Render(new Cmd{position=view.camera.transform.position,target=view.camera.transform.position+view.camera.transform.forward*30,file="house-current-view.png"});}foreach(var n in new[]{"West cloister bay 1","West cloister bay 2","West cloister bay 3","West cloister bay 4","West cloister bay 5"}){var g=GameObject.Find(n);var vv=Points(g);var b=new Bounds(vv[0],Vector3.zero);foreach(var p in vv)b.Encapsulate(p);float lo=1000,hi=-1000;for(float x=b.min.x;x<=b.max.x;x+=.25f)for(float z=b.min.z;z<=b.max.z;z+=.25f){float h=GH(x,z);lo=Mathf.Min(lo,h);hi=Mathf.Max(hi,h);}sb.AppendLine(n+" root "+g.transform.position+" bounds "+b+" terrain "+lo+".."+hi);foreach(var f in g.GetComponentsInChildren<MeshFilter>()){var r=f.GetComponent<Renderer>();if(r&&r.enabled)sb.AppendLine("mesh "+f.name+" "+r.bounds);}}File.WriteAllText(HD+"survey.txt",sb.ToString());}
 static void RefineFoundations(){foreach(var name in new[]{"Sanctuary terrace foundation","Staircase foundation"}){var g=GameObject.Find(name);var m=g.GetComponent<MeshFilter>().sharedMesh;var b=m.bounds;var vv=m.vertices;float add=name.StartsWith("Sanctuary")?.24f:.34f;for(int i=0;i<vv.Length;i++){var p=vv[i];p.x=b.center.x+(p.x-b.center.x)*(b.size.x+add)/b.size.x;p.z=b.center.z+(p.z-b.center.z)*(b.size.z+add)/b.size.z;if(p.y<b.max.y-.1f)p.y=Mathf.Min(b.max.y-.15f,GH(p.x,p.z)-.38f);vv[i]=p;}m.vertices=vv;m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();g.GetComponent<MeshCollider>().sharedMesh=null;g.GetComponent<MeshCollider>().sharedMesh=m;EditorUtility.SetDirty(m);}AssetDatabase.SaveAssets();Physics.SyncTransforms();VerifyFoundations();}
 static void VerifyFoundations(){
 var root=GameObject.Find("11 - Terrain-fitted foundations");if(!root)throw new Exception("Missing foundations");Physics.SyncTransforms();var cc=root.GetComponentsInChildren<MeshCollider>();var report=JsonUtility.FromJson<GroundReport>(File.ReadAllText(GD+"audit.json"));var log=new System.Text.StringBuilder();int tested=0,fail=0;
 foreach(var it in report.items.Where(i=>i.name.StartsWith("Temple of")||i.name.StartsWith("Temple apron")||i.name.StartsWith("Broad temple ascent")||i.name.StartsWith("Terrace front")||i.name.StartsWith("Sanctuary east arcade")||new[]{"West cloister bay 4","West cloister bay 5","East cloister bay 4","East cloister turning pavilion","Outer west low boundary 1","Outer west low boundary 3","Exposed east cloister arch","East breached wall stump"}.Contains(i.name))){int bad=0;float max=0;foreach(var p in it.bottom){float support=GH(p.x,p.z);foreach(var c in cc){RaycastHit h;if(c.Raycast(new Ray(new Vector3(p.x,100,p.z),Vector3.down),out h,150))support=Mathf.Max(support,h.point.y);}float gap=it.min.y-support;if(gap>.2f)bad++;max=Mathf.Max(max,gap);tested++;}fail+=bad;log.AppendLine(it.name+": "+it.bottom.Length+" samples, unsupported="+bad+", maxGap="+max.ToString("F3"));}
 foreach(var c in cc){var vv=c.sharedMesh.vertices;int bottoms=0;float highest=float.MinValue;for(int i=0;i<vv.Length;i+=1){var p=c.transform.TransformPoint(vv[i]);if(p.y<c.bounds.max.y-.1f){highest=Mathf.Max(highest,p.y-GH(p.x,p.z));bottoms++;}}log.AppendLine(c.name+": "+bottoms+" skirt samples, max terrain clearance="+highest.ToString("F3"));}
 log.AppendLine("TOTAL "+tested+" architecture foot samples; unsupported (>0.2m): "+fail);File.WriteAllText(GD+"verification.txt",log.ToString());
 }
